import fs from "node:fs/promises";
import path from "node:path";
import type { ReactNode } from "react";
import Image from "next/image";
import Link from "next/link";
import { ProductSheet } from "@/components/ProductSheet";
import { localizedHref, type Locale } from "@/i18n/config";
import { t } from "@/i18n/t";
import { ui } from "@/i18n/ui";
import type { Loc } from "@/i18n/t";
import type { NutritionFacts } from "@/lib/content";
import { sizeBucketIds } from "@/lib/pack-sizes";
// Generated by scripts/compute-image-frames.mjs: where the product sits in each photo.
import frames from "@/lib/image-frames.json";

export type CatalogProduct = {
  slug: string;
  name: Loc;
  description: Loc;
  image: string;
  details?: Loc[];
  imageFit?: "cover" | "contain";
  nutrition?: NutritionFacts;
  unavailableForExport?: boolean;
  href?: string;
};

/** Brands whose name appears in a product's `details`, mapped to their logo. */
const BRAND_LOGOS: Record<string, string> = {
  "Akhan Makarna": "/brands/akhan-logo.png",
  "Chupa Chups": "/brands/chupa-chups-logo.png",
  "Fresh Elements": "/brands/fresh-elements-logo.png",
  Lasco: "/brands/lasco.png",
  "Quinoa Club": "/brands/quinoa-club-logo.png",
  "Star Grocery": "/brands/star-grocery-logo.png",
  StarKist: "/brands/starkist-logo.jpg",
  Tronix: "/brands/tronix.png",
};

/** Product lines that carry their parent brand's logo and are filtered under it. */
const SUB_BRANDS: Record<string, string> = {
  "StarKist Selects": "StarKist",
};

/** Brand and sub-brand names that have no logo on file; shown as text instead. */
const TEXT_BRANDS = new Set([
  "APack Ready Meals",
  "Food Life Balanced",
  "Food Life Balanced+",
  "Joy2",
  "Joy2 Yo-2-Go",
  "Ready Ration",
  "Flint",
  "Flint · Hroom",
  "Khutorok",
  "Kitto",
  "La Pasta",
  "Pansky",
  "Perfetto",
  "The Banka",
]);

/** A pack size such as "16 oz", "250 g / 500 g / 25 kg" or "2.6 oz pouch". */
const SIZE_PATTERN = /\d[\d.,]*\s*(?:g|kg|oz|fl\.?\s?oz|ml|cl|l|lb|lbs)\b/i;

/** Warm backdrop behind photos that have no background of their own. */
const PHOTO_BG_HEX = "#f4f1ea";

type ProductView = {
  product: CatalogProduct;
  name: string;
  image: string;
  logo?: { src: string; alt: string };
  textBrand?: string;
  /** The brand used for filtering: the logo brand, else the text brand. */
  brand?: string;
  size?: string;
  /** The size in English, for sorting into the Size filter's ranges. */
  sizeEn?: string;
  tags: string[];
};

/**
 * Splits a product's free-form `details` into the slots the card and the
 * details window show: brand (logo or text), pack size, and the remaining tags.
 */
function toView(product: CatalogProduct, image: string, locale: Locale, fallbackBrand?: string): ProductView {
  let logo: ProductView["logo"];
  let textBrand: string | undefined;
  let size: string | undefined;
  let sizeEn: string | undefined;
  const tags: string[] = [];

  for (const detail of product.details ?? []) {
    const key = detail.en.trim();
    if (BRAND_LOGOS[key]) {
      logo ??= { src: BRAND_LOGOS[key], alt: key };
    } else if (SUB_BRANDS[key]) {
      const parent = SUB_BRANDS[key];
      logo ??= { src: BRAND_LOGOS[parent], alt: parent };
      textBrand ??= t(locale, detail);
    } else if (TEXT_BRANDS.has(key)) {
      textBrand ??= t(locale, detail);
    } else if (!size && SIZE_PATTERN.test(key)) {
      size = t(locale, detail);
      sizeEn = key;
    } else {
      tags.push(t(locale, detail));
    }
  }

  if (!logo && !textBrand && fallbackBrand) {
    if (BRAND_LOGOS[fallbackBrand]) logo = { src: BRAND_LOGOS[fallbackBrand], alt: fallbackBrand };
    else textBrand = fallbackBrand;
  }

  return {
    product,
    name: t(locale, product.name),
    image,
    logo,
    textBrand,
    brand: logo?.alt ?? textBrand,
    size,
    sizeEn,
    tags,
  };
}

async function productImageSrc(src: string): Promise<string> {
  if (!src.startsWith("/products/")) return src;
  try {
    const file = await fs.stat(path.join(process.cwd(), "public", src));
    return `${src}?v=${Math.trunc(file.mtimeMs)}`;
  } catch {
    return src;
  }
}

type ImageFrame = { aspect: number; x: number; y: number; w: number; h: number; bg: string | null };
const imageFrames = frames as Record<string, ImageFrame>;

/**
 * How a photo fills its square: scene photos are cropped to cover it; pack shots
 * sitting small on a plain or transparent background are zoomed so the pack
 * itself fills the square, over the photo's own background colour.
 */
type Placement =
  | { kind: "cover" }
  | { kind: "pack"; bg: string; blend: boolean; left: number; top: number; width: number; height: number };

function placement(product: CatalogProduct, fill: number): Placement {
  const frame = imageFrames[product.image];
  if (!frame) return { kind: "cover" };
  const contentArea = frame.w * frame.h;
  if (frame.bg !== null && contentArea >= 0.85) return { kind: "cover" };

  // Scale the photo (in % of the square) so the product's box spans `fill` of its longer side.
  const width = fill / Math.max(frame.w, frame.h / frame.aspect);
  const height = width / frame.aspect;
  return {
    kind: "pack",
    bg: frame.bg ?? PHOTO_BG_HEX,
    // Opaque photos blend with "darken" so their background melts into the matching card colour.
    blend: frame.bg !== null,
    left: 0.5 - (frame.x + frame.w / 2) * width,
    top: 0.5 - (frame.y + frame.h / 2) * height,
    width,
    height,
  };
}

/** The product photo inside a square box; the box itself sets the size. */
function SquarePhoto({
  src,
  alt,
  place,
  sizesVw,
  className = "",
}: {
  src: string;
  alt: string;
  place: Placement;
  /** Width of the square as viewport %, per breakpoint: [phone, tablet, desktop]. */
  sizesVw: [number, number, number];
  className?: string;
}) {
  const scale = place.kind === "pack" ? Math.max(1, place.width) : 1;
  const [phone, tablet, desktop] = sizesVw.map((vw) => Math.min(100, Math.ceil(vw * scale)));
  const sizes = `(max-width: 767px) ${phone}vw, (max-width: 1279px) ${tablet}vw, ${desktop}vw`;

  if (place.kind === "cover") {
    return <Image src={src} alt={alt} fill className={`object-cover ${className}`} sizes={sizes} />;
  }
  const pct = (value: number) => `${(value * 100).toFixed(2)}%`;
  return (
    <div
      className={`absolute ${place.blend ? "mix-blend-darken" : ""} ${className}`}
      style={{ left: pct(place.left), top: pct(place.top), width: pct(place.width), height: pct(place.height) }}
    >
      <Image src={src} alt={alt} fill className="object-fill" sizes={sizes} />
    </div>
  );
}

function BrandMark({ view, size }: { view: ProductView; size: "card" | "modal" }) {
  if (view.logo) {
    return (
      <span className={`relative block ${size === "card" ? "h-9 w-32" : "h-11 w-44"}`}>
        <Image
          src={view.logo.src}
          alt={view.logo.alt}
          fill
          className={`object-contain ${size === "card" ? "object-center" : "object-left"}`}
          sizes={size === "card" ? "128px" : "176px"}
        />
      </span>
    );
  }
  if (view.textBrand) {
    return (
      <span
        className={`flex items-center text-[10px] font-bold tracking-[0.08em] text-gold-ink uppercase sm:text-[11px] sm:tracking-[0.14em] ${
          size === "card" ? "min-h-9 justify-center" : ""
        }`}
      >
        {view.textBrand}
      </span>
    );
  }
  return null;
}

/** US-style Nutrition Facts panel, built from whatever values the product has on file. */
function NutritionLabel({ nutrition, locale }: { nutrition: NutritionFacts; locale: Locale }) {
  const rows = [
    nutrition.totalFat ? { label: t(locale, ui.categoryPage.totalFat), value: nutrition.totalFat } : null,
    nutrition.sodium ? { label: t(locale, ui.categoryPage.sodium), value: nutrition.sodium } : null,
    nutrition.totalCarbohydrate
      ? { label: t(locale, ui.categoryPage.totalCarbohydrate), value: nutrition.totalCarbohydrate }
      : null,
    nutrition.protein ? { label: t(locale, ui.categoryPage.protein), value: nutrition.protein } : null,
  ].filter((row): row is { label: string; value: string } => row !== null);

  return (
    <section
      aria-label={t(locale, ui.categoryPage.nutritionFacts)}
      className="mx-auto w-full max-w-[17rem] border-2 border-black bg-white px-2 py-1.5 text-black"
    >
      <h3 className="text-[1.9rem] leading-none font-black tracking-tight">
        {t(locale, ui.categoryPage.nutritionFacts)}
      </h3>
      <div className="mt-1 border-b-[10px] border-black pb-1">
        {nutrition.servingsPerContainer ? (
          <p className="text-[13px]">{t(locale, nutrition.servingsPerContainer)}</p>
        ) : null}
        <p className="flex items-baseline justify-between gap-2 text-[13px] font-bold">
          <span>{t(locale, ui.categoryPage.servingSize)}</span>
          <span className="text-right">{t(locale, nutrition.servingSize)}</span>
        </p>
      </div>
      <div className="border-b-[5px] border-black pt-1 pb-0.5">
        <p className="text-[11px] font-bold">{t(locale, ui.categoryPage.amountPerServing)}</p>
        <p className="flex items-end justify-between gap-2">
          <span className="text-2xl leading-none font-black">{t(locale, ui.categoryPage.calories)}</span>
          <span className="text-[2.5rem] leading-none font-black">{nutrition.calories}</span>
        </p>
      </div>
      <dl className="text-[13px]">
        {rows.map((row) => (
          <div key={row.label} className="flex justify-between gap-2 border-b border-black/60 py-0.5 last:border-b-0">
            <dt className="font-bold">{row.label}</dt>
            <dd>{row.value}</dd>
          </div>
        ))}
      </dl>
    </section>
  );
}

function TagChip({ children }: { children: ReactNode }) {
  return (
    <li className="inline-flex items-center gap-1.5 rounded-full border border-[#e5e0d6] bg-white px-2.5 py-1 text-[10px] font-bold tracking-[0.06em] text-ink/75 uppercase">
      <span aria-hidden="true" className="h-1.5 w-1.5 shrink-0 rounded-full bg-[#1f9d55]" />
      {children}
    </li>
  );
}

function ProductCard({ view, locale }: { view: ProductView; locale: Locale }) {
  const { product, name } = view;
  const place = placement(product, 0.86);
  const actionLabel = t(locale, product.href ? ui.categoryPage.viewAllProducts : ui.categoryPage.viewDetails);

  return (
    <article
      id={product.href ? product.slug : undefined}
      className="group relative flex h-full flex-col overflow-hidden rounded-2xl border border-[#ede8df] bg-white shadow-[0_1px_4px_rgba(0,0,0,0.05)] transition duration-200 hover:-translate-y-0.5 hover:shadow-xl hover:shadow-ink/10 motion-reduce:hover:translate-y-0"
    >
      <div
        className="relative aspect-square overflow-hidden"
        style={{ background: place.kind === "pack" ? place.bg : PHOTO_BG_HEX }}
      >
        <SquarePhoto
          src={view.image}
          alt={name}
          place={place}
          sizesVw={[50, 33, 25]}
          className="transition duration-300 group-hover:scale-[1.04] motion-reduce:group-hover:scale-100"
        />
        {view.size ? (
          <span className="absolute top-2.5 left-2.5 max-w-[calc(100%-1.25rem)] truncate rounded-full bg-white px-2.5 py-1 text-xs font-semibold text-ink uppercase shadow-[0_1px_6px_rgba(0,0,0,0.12)] sm:top-3.5 sm:left-3.5 sm:px-3 sm:py-1.5 sm:text-sm">
            {view.size}
          </span>
        ) : null}
        <div
          aria-hidden="true"
          className="absolute inset-0 hidden items-center justify-center bg-ink/0 opacity-0 transition duration-200 group-hover:bg-ink/25 group-hover:opacity-100 sm:flex"
        >
          <span className="rounded-full bg-white px-4 py-2 text-sm font-semibold text-ink shadow-lg">
            {actionLabel}
          </span>
        </div>
      </div>

      <div className="flex flex-col items-center gap-1.5 border-t border-[#ede8df] px-3 pt-3.5 pb-4 text-center sm:px-5 sm:pt-4 sm:pb-5">
        <BrandMark view={view} size="card" />
        <h3 className="line-clamp-3 font-serif text-[15px] leading-snug font-bold text-[#1d1a16] sm:text-[19px]">
          {name}
        </h3>
        {product.unavailableForExport ? (
          <p className="text-[10px] font-semibold tracking-wide text-gold-ink uppercase">
            {t(locale, ui.categoryPage.notAvailableForExport)}
          </p>
        ) : null}
      </div>

      {view.tags.length > 0 ? (
        <ul className="mt-auto hidden flex-wrap content-start justify-center gap-1.5 border-t border-[#ede8df] px-3 py-3.5 sm:flex">
          {view.tags.map((tag) => (
            <TagChip key={tag}>{tag}</TagChip>
          ))}
        </ul>
      ) : null}

      {product.href ? null : (
        <ProductSheet
          label={`${t(locale, ui.categoryPage.viewDetails)}: ${name}`}
          closeLabel={t(locale, ui.categoryPage.closeDetails)}
          title={name}
        >
          <ProductDetail view={view} locale={locale} />
        </ProductSheet>
      )}
    </article>
  );
}

/** The contents of the details window: photo, product information and nutrition facts. */
function ProductDetail({ view, locale }: { view: ProductView; locale: Locale }) {
  const { product, name } = view;
  const nutrition = product.nutrition;
  const inquireHref = `${localizedHref(locale, "/contact")}?product=${encodeURIComponent(name)}`;
  const greyChips = [view.logo ? view.textBrand : undefined, view.size].filter(Boolean) as string[];
  const detailPlace = placement(product, 0.8);

  return (
    <div
      className={`grid lg:h-[min(88dvh,760px)] ${
        nutrition
          ? "lg:grid-cols-[minmax(0,1.15fr)_minmax(0,1fr)_19rem]"
          : "lg:grid-cols-[minmax(0,1.15fr)_minmax(0,1fr)]"
      }`}
    >
      {/*
        The photo sits in the largest square that fits the panel. Pack shots are painted in their
        own background colour around it; scene photos get a soft blurred copy of themselves.
      */}
      <div
        className="relative aspect-square overflow-hidden [container-type:size] sm:aspect-[4/3] lg:aspect-auto lg:h-full"
        style={{ background: detailPlace.kind === "pack" ? detailPlace.bg : PHOTO_BG_HEX }}
      >
        {detailPlace.kind === "cover" ? (
          <Image
            src={view.image}
            alt=""
            aria-hidden="true"
            fill
            className="scale-110 object-cover opacity-70 blur-2xl"
            sizes="(max-width: 1023px) 50vw, 20vw"
          />
        ) : null}
        <div className="absolute top-1/2 left-1/2 h-[min(100cqw,100cqh)] w-[min(100cqw,100cqh)] -translate-x-1/2 -translate-y-1/2 overflow-hidden">
          <SquarePhoto src={view.image} alt={name} place={detailPlace} sizesVw={[100, 75, 45]} />
        </div>
      </div>

      <div className="flex min-h-0 flex-col p-5 sm:p-8 lg:overflow-y-auto lg:p-10">
        <BrandMark view={view} size="modal" />
        <h2 className="mt-3 font-serif text-[1.75rem] leading-tight font-bold text-[#1d1a16] sm:text-[2.1rem]">
          {name}
        </h2>

        {greyChips.length > 0 ? (
          <div className="mt-4 flex flex-wrap gap-2">
            {greyChips.map((chip) => (
              <span key={chip} className="rounded-lg bg-[#efebe4] px-3 py-1.5 text-sm font-semibold text-ink/80">
                {chip}
              </span>
            ))}
          </div>
        ) : null}

        {view.tags.length > 0 ? (
          <ul className="mt-3 flex flex-wrap gap-2">
            {view.tags.map((tag) => (
              <li
                key={tag}
                className="rounded-md border border-[#1f9d55]/30 bg-[#effaf3] px-2.5 py-1 text-[11px] font-bold tracking-[0.06em] text-[#17713f] uppercase"
              >
                {tag}
              </li>
            ))}
          </ul>
        ) : null}

        {product.unavailableForExport ? (
          <p className="mt-3 inline-flex self-start rounded-full bg-gold/10 px-2.5 py-1 text-[11px] font-semibold tracking-wide text-gold-ink uppercase">
            {t(locale, ui.categoryPage.notAvailableForExport)}
          </p>
        ) : null}

        <div className="mt-6 border-t border-line pt-6">
          <p className="text-xs font-semibold tracking-[0.14em] text-slate/80 uppercase">
            {t(locale, ui.categoryPage.description)}
          </p>
          <p className="mt-3 text-base leading-relaxed text-slate">{t(locale, product.description)}</p>
        </div>

        <div className="mt-auto pt-8">
          <div className="border-t border-line pt-6">
            <a
              href={inquireHref}
              className="flex w-full items-center justify-center gap-2 rounded-xl bg-brand px-5 py-4 text-base font-bold text-white shadow-lg shadow-brand/20 transition hover:bg-brand-deep"
            >
              {t(locale, ui.categoryPage.inquireProduct)}
              <span aria-hidden="true">→</span>
            </a>
            <p className="mt-3 text-center text-sm text-slate/80">{t(locale, ui.categoryPage.inquireNote)}</p>
          </div>
        </div>
      </div>

      {nutrition ? (
        <div className="border-t border-line bg-white p-5 pb-8 sm:p-8 lg:overflow-y-auto lg:border-t-0 lg:border-l lg:px-6 lg:pt-20">
          <NutritionLabel nutrition={nutrition} locale={locale} />
        </div>
      ) : null}
    </div>
  );
}

function CardLink({ view, locale }: { view: ProductView; locale: Locale }) {
  return view.product.href ? (
    <Link href={localizedHref(locale, view.product.href)} className="block h-full rounded-2xl">
      <ProductCard view={view} locale={locale} />
    </Link>
  ) : (
    <ProductCard view={view} locale={locale} />
  );
}

export type CatalogEntry = {
  slug: string;
  name: string;
  brand?: string;
  /** Size-range ids from `sizeBuckets` in lib/pack-sizes. */
  sizes: string[];
  /** Lower-cased name, brand, tags and description for the search box. */
  searchText: string;
  card: ReactNode;
};

/** Server-renders each product's card (with its details window) for the filterable catalog. */
export async function buildCatalogEntries(
  items: { product: CatalogProduct; brand?: string }[],
  locale: Locale,
): Promise<CatalogEntry[]> {
  const images = await Promise.all(items.map(({ product }) => productImageSrc(product.image)));
  return items.map(({ product, brand }, index) => {
    const view = toView(product, images[index], locale, brand);
    return {
      slug: product.slug,
      name: view.name,
      brand: view.brand,
      sizes: sizeBucketIds(view.sizeEn),
      searchText: [view.name, view.brand, view.textBrand, ...view.tags, t(locale, product.description)]
        .filter(Boolean)
        .join(" ")
        .toLowerCase(),
      card: <CardLink view={view} locale={locale} />,
    };
  });
}

export async function ProductGrid({
  products,
  locale,
  brand,
}: {
  products: CatalogProduct[];
  locale: Locale;
  /** Brand to show on cards whose details don't name one, e.g. on a single-brand page. */
  brand?: string;
}) {
  const imageSources = await Promise.all(products.map((product) => productImageSrc(product.image)));
  const views = products.map((product, index) => toView(product, imageSources[index], locale, brand));

  return (
    <div className="mt-6 grid grid-cols-2 gap-3 sm:mt-8 sm:gap-5 md:grid-cols-3 xl:grid-cols-4">
      {views.map((view) => (
        <CardLink key={view.product.slug} view={view} locale={locale} />
      ))}
    </div>
  );
}
